{
  "passageId": "neoclassicism-romanticism-art",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "귀족의 향락을 주제로 삼았다는 사실이 로코코를 경박하고 부도덕하다고 판단한 근거이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "장식적 기교에 치중했다는 사실이 로코코에 대한 부정적 평가를 뒷받침한다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 견해의 충돌이 아니라 계몽주의자의 미술관을 기준으로 로코코와 고전주의에 대한 평가가 대비된다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "고전주의가 계몽주의자의 지향에 부합했다는 사실로 계몽주의가 고전주의의 재등장에 영향을 미친 이유를 설명한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "사물에 본래 있는 특질이라는 일반적 설명을 비례·조화·질서라는 구체적인 특질로 풀어 준다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "플라톤의 발언은 아름다움을 객관적 비례에서 찾는 관점을 보여 주는 예로 제시된다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "아름다움이 사물의 객관적 형식에 내재한다는 관점이 기하학적 조형성을 갖춘 사물 자체가 즐거움을 준다는 설명을 뒷받침한다."
    },
    {
      "id": "R8",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "고전주의의 객관적 미학이 빈켈만의 고대 그리스 미술 평가와 모방 주장에 적용된다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "모방 대상으로 제시된 고귀한 단순성과 고요한 위대함이라는 용어의 뜻을 풀이한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "육체적 아름다움과 정신적 숭고함의 완벽한 일치가 절대미가 구현되었다는 평가의 근거이다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "고대 그리스 미술에 절대미가 구현되었다는 평가를 이유로 그것을 전범으로 삼아 모방해야 한다는 당위를 세운다."
    },
    {
      "id": "R12",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "신고전주의 화가들이 빈켈만의 미학을 실제 작품 제작의 규범과 표현 방식에 가져다 쓴다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "고전주의 규범을 준수한 결과 작품에 매끈한 표면과 뚜렷한 윤곽선 및 안정된 구도가 나타난다."
    },
    {
      "id": "R14",
      "type": "CAUSE",
      "otherName": "",
      "reason": "고전주의 규범의 준수가 색채보다 형태를 강조하는 실제 표현상의 특징으로 이어진다."
    },
    {
      "id": "R15",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "계몽주의의 영향은 화가들이 도덕적 시민 양성을 위한 사회적 교훈을 지향하게 된 사상적 배경이다."
    },
    {
      "id": "R16",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "도덕적 시민 양성을 위한 사회적 교훈을 전달하려고 애국적 희생을 보여 주는 영웅 이야기를 주제로 선택한다."
    },
    {
      "id": "R17",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "정신적 숭고함과 도덕성을 드러내려는 목적을 위해 영웅의 표정을 침착하게 표현한다."
    },
    {
      "id": "R18",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "고요한 위대함이라는 미학적 원리가 실제 작품 속 영웅의 침착한 표정과 감정 절제에 적용된다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "시민 사회에 부합하는 미술이라는 지향을 도덕적 교훈과 애국적 영웅이라는 구체적인 작품 주제로 풀어 보여 준다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "개체의 고유성과 독자성을 인정하는 헤르더 자신의 전제가 빈켈만을 비판하는 근거로 쓰인다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "각 개체의 가치가 동등하다는 전제가 고대 그리스 미술을 보편적 이상으로 특권화한 견해에 대한 비판을 뒷받침한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "변화와 시간의 흐름을 중시한다는 전제에서 초시대적 모방론이 시대착오적이라는 판단이 나온다."
    },
    {
      "id": "R23",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "헤르더가 빈켈만의 절대적이고 보편적인 미의 관점을 직접 문제 삼는다."
    },
    {
      "id": "R24",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "헤르더가 고대 그리스 미술을 모방해야 한다는 빈켈만의 주장을 시대착오적이라고 공격한다."
    },
    {
      "id": "R25",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "헤르더의 상대주의적 비판이 신고전주의를 거부하는 낭만주의가 등장한 사상적 계기로 제시된다."
    },
    {
      "id": "R26",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "헤르더의 사상에 따른 개인의 각성과 자기표현 미술의 등장이 낭만주의의 개인 중심적 지향이 형성되는 배경이다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "흄의 발언은 아름다움의 근원을 감상자의 마음에서 찾는 낭만주의의 관점을 보여 주는 예이다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "사물 자체에 미추가 정해져 있지 않다는 미학적 관점이 기존에 배제되었던 영역으로 실제 작품 주제가 확장되는 데 작용한다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "자유로운 감정 표현이라는 일반적 특징을 강렬한 채색과 거친 붓 자국 및 역동적 구도라는 세부 표현 방식으로 보여 준다."
    },
    {
      "id": "R30",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "아름다움의 근원을 사물의 객관적 특질에 두는 고전주의와 감상자의 마음에 두는 낭만주의의 견해를 나란히 비교한다."
    },
    {
      "id": "R31",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "견해 자체가 아니라 작품의 표면 처리와 구도라는 동일한 기준에서 두 사조의 표현상 특징이 대비된다."
    },
    {
      "id": "R32",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "실제 작품에서 형태와 색채 중 무엇을 강조하는지를 기준으로 두 사조의 표현 방식이 대비된다."
    },
    {
      "id": "R33",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "감정의 절제로 도덕성을 드러내려는 신고전주의의 입장과 자유로운 감정 표현을 중시하는 낭만주의의 입장이 다르다."
    },
    {
      "id": "R34",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "신고전주의에서 낭만주의로 시대가 옮겨 가며 미술의 주제 범위가 영웅 이야기에서 불안과 공포 및 환상적 존재로 넓어진다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "폭넓은 주제와 다양한 감정 표현이라는 특징이 개별성과 다양성을 꽃피운 사조라는 종합적 평가를 뒷받침한다."
    },
    {
      "id": "R36",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "낭만주의가 신고전주의의 객관적·절대적 미와 규범 중심 입장을 거부하는 대립적 사조로 제시된다."
    }
  ]
}

